<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= html_escape($title); ?></title><link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/@tabler/core@1.4.0/dist/css/tabler.min.css"><link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/@tabler/icons-webfont@3.34.1/dist/tabler-icons.min.css"><link href="https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;600;700;800;900&display=swap" rel="stylesheet"><script defer src="<?= base_url('assets/battle-room-timer.js?v=20260812'); ?>"></script><style>
body{font-family:'Plus Jakarta Sans',sans-serif;background:linear-gradient(135deg,#fdf2f8,#f5f3ff);min-height:100vh}.wrap{max-width:760px;margin:auto;padding:18px 16px 50px}.players{display:grid;grid-template-columns:repeat(auto-fit,minmax(145px,1fr));gap:9px;margin-bottom:16px}.player{background:#fff;border-radius:14px;padding:11px 13px;box-shadow:0 3px 14px #0001}.player.me{outline:2px solid #9333ea}.nm{font-size:.82rem;font-weight:700;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.sc{font-size:1.4rem;font-weight:900}.pbar{height:6px;background:#eee;border-radius:9px;overflow:hidden}.pbar div{height:100%;background:#9333ea}.panel{background:#fff;border-radius:20px;padding:26px;box-shadow:0 6px 24px #0001;text-align:center}.qtext{font-size:1.3rem;font-weight:800;color:#1e1b4b;margin:8px 0 18px}.opt{display:flex;width:100%;align-items:center;gap:12px;border:2px solid #e2e8f0;background:#fff;border-radius:14px;padding:14px 16px;margin-top:10px;text-align:left}.opt.correct{border-color:#16a34a;background:#f0fdf4}.opt.wrong{border-color:#dc2626;background:#fef2f2}.opt-l{width:28px;height:28px;border-radius:50%;background:#f1f5f9;display:grid;place-items:center;font-weight:800}.code{font:900 2rem monospace;letter-spacing:6px;color:#9333ea;background:#faf5ff;border:2px dashed #d8b4fe;border-radius:16px;padding:14px}.roster{display:flex;flex-wrap:wrap;gap:7px;justify-content:center;margin:16px 0}.chip{padding:7px 11px;border-radius:99px;background:#f1f5f9;font-weight:700;font-size:.8rem}.spin{width:42px;height:42px;border:5px solid #eee;border-top-color:#9333ea;border-radius:50%;animation:sp 1s linear infinite;margin:15px auto}@keyframes sp{to{transform:rotate(360deg)}}.ranking{text-align:left;margin:15px 0}.rank{display:grid;grid-template-columns:36px 1fr auto;gap:8px;padding:10px;border-bottom:1px solid #eee}.rank:first-child{background:#fffbeb;border-radius:12px}.muted{color:#64748b;font-size:.85rem}</style></head><body>
<div class="wrap"><div class="d-flex justify-content-between mb-3"><a href="<?= base_url('belajar/battle'); ?>" class="btn btn-sm btn-white">← Keluar</a><div><span class="badge bg-red text-white me-1"><i class="ti ti-clock"></i> <span id="battle-timer">--:--</span></span><span class="badge bg-purple text-white">Room <?= html_escape($room['code']); ?></span></div></div><div class="players" id="players"></div>
<div class="panel" id="waiting" hidden><h3>Ruang Tunggu</h3><p class="muted">Bagikan kode, lalu host memulai setelah minimal 2 pemain bergabung.</p><div class="code"><?= html_escape($room['code']); ?></div><div class="roster" id="roster"></div><p id="capacity" class="muted"></p><?php if(!empty($participant['is_host'])): ?><button id="start" class="btn btn-primary" disabled><i class="ti ti-player-play"></i> Mulai Battle</button><?php else: ?><div class="spin"></div><p class="muted">Menunggu host memulai…</p><?php endif; ?></div>
<div class="panel" id="question" hidden><div class="muted">Soal <span id="qnum">1</span> dari <?= count($questions); ?></div><div class="qtext" id="qtext"></div><div id="options"></div></div><div class="panel" id="done" hidden><div style="font-size:3rem">✅</div><h3>Kamu sudah selesai!</h3><p class="muted">Waktu selesai sudah tercatat. Menunggu pemain lain…</p><div class="spin"></div></div><div class="panel" id="result" hidden><div style="font-size:3.4rem" id="emoji">🏆</div><h2 id="title">Hasil Battle</h2><p class="muted">Pemenang ditentukan dari waktu selesai paling awal.</p><div class="ranking" id="ranking"></div><div class="d-flex gap-2"><a href="<?= base_url('belajar/battle'); ?>" class="btn btn-outline-primary flex-fill">Main Lagi</a><a href="<?= base_url('belajar'); ?>" class="btn btn-primary flex-fill">Arena Belajar</a></div></div></div>
<script>(function(){'use strict';var CODE=<?= json_encode($room['code']); ?>,UID=<?= (int)$user['id']; ?>,QS=<?= $q_json; ?>,N=QS.length,progress=<?= (int)$participant['progress']; ?>,finished=<?= !empty($participant['finished'])?'true':'false'; ?>,busy=false,resultShown=false,csrfName=<?= json_encode($this->security->get_csrf_token_name()); ?>,csrf=<?= json_encode($this->security->get_csrf_hash()); ?>;var ids=['waiting','question','done','result'];function show(x){ids.forEach(function(id){document.getElementById(id).hidden=id!==x;});}function post(url,data){var b=new URLSearchParams(data);b.append(csrfName,csrf);return fetch(url,{method:'POST',headers:{'X-Requested-With':'XMLHttpRequest','Content-Type':'application/x-www-form-urlencoded'},body:b}).then(function(r){return r.json();});}function esc(s){var d=document.createElement('div');d.textContent=s||'';return d.innerHTML;}function renderQ(){if(progress>=N){finished=true;show('done');return;}var q=QS[progress];qnum.textContent=progress+1;qtext.textContent=q.question;options.innerHTML='';q.options.forEach(function(o,i){var b=document.createElement('button');b.className='opt';b.innerHTML='<span class="opt-l">'+['A','B','C','D'][i]+'</span><span>'+esc(o)+'</span>';b.onclick=function(){answer(i);};options.appendChild(b);});show('question');}function answer(i){if(busy)return;busy=true;document.querySelectorAll('.opt').forEach(function(x){x.disabled=true;});post(<?= json_encode(base_url('belajar/battle/answer')); ?>,{code:CODE,index:progress,selected:i}).then(function(j){if(!j.ok)throw Error(j.message||'Gagal');if(j.ignored){progress=j.progress;busy=false;renderQ();return;}var os=document.querySelectorAll('.opt');if(os[j.correct])os[j.correct].classList.add('correct');if(!j.is_correct&&os[i])os[i].classList.add('wrong');setTimeout(function(){progress=j.progress;finished=j.finished;busy=false;j.finished?show('done'):renderQ();poll();},650);}).catch(function(e){busy=false;alert(e.message);document.querySelectorAll('.opt').forEach(function(x){x.disabled=false;});});}function apply(s){players.innerHTML=s.players.map(function(p){return '<div class="player '+(p.user_id===UID?'me':'')+'"><div class="nm">'+esc(p.name)+(p.is_host?' 👑':'')+'</div><div class="sc">'+p.score+'</div><div class="pbar"><div style="width:'+(p.progress/N*100)+'%"></div></div></div>';}).join('');roster.innerHTML=s.players.map(function(p){return '<span class="chip">'+esc(p.name)+(p.is_host?' · Host':'')+'</span>';}).join('');capacity.textContent=s.max_players===null?s.players.length+' pemain · tanpa batas':s.players.length+' / '+s.max_players+' pemain';var sb=document.getElementById('start');if(sb)sb.disabled=s.players.length<2;if(s.status==='finished'){showResult(s);return;}if(s.status==='waiting'){show('waiting');return;}var me=s.players.find(function(p){return p.user_id===UID;});if(me){progress=me.progress;finished=me.finished;}if(finished)show('done');else if(document.getElementById('question').hidden)renderQ();}function showResult(s){if(resultShown)return;resultShown=true;var sorted=s.players.slice().sort(function(a,b){return String(a.finished_at).localeCompare(String(b.finished_at));}),won=s.winner_user_id===UID;emoji.textContent=won?'🏆':'👏';title.textContent=won?'Kamu Juara!':'Battle Selesai';ranking.innerHTML=sorted.map(function(p,i){return '<div class="rank"><b>#'+(i+1)+'</b><span>'+esc(p.name)+(p.user_id===UID?' (Kamu)':'')+'</span><span><b>'+p.score+'</b>/'+N+'</span></div>';}).join('');show('result');}function poll(){fetch(<?= json_encode(base_url('belajar/battle/state/')); ?>+CODE,{headers:{'X-Requested-With':'XMLHttpRequest'}}).then(function(r){return r.json();}).then(function(j){if(j.ok)apply(j.state);});}var start=document.getElementById('start');if(start)start.onclick=function(){start.disabled=true;post(<?= json_encode(base_url('belajar/battle/start')); ?>,{code:CODE}).then(function(j){if(!j.ok)throw Error(j.message);poll();}).catch(function(e){alert(e.message);start.disabled=false;});};poll();setInterval(poll,1200);})();</script></body></html>
